package com.aoo.bcg.common.transaction;import java.time.Duration;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ConsistencyRoutingPolicyTest{@Test void writesAndStrongReadsUsePrimaryAndLaggingReplicaFallsBack(){var p=new ConsistencyRoutingPolicy();assertEquals(ConsistencyRoutingPolicy.Target.PRIMARY,p.route(new ConsistencyRoutingPolicy.Request(ConsistencyRoutingPolicy.Intent.AUTHORITATIVE_WRITE,0,Duration.ZERO),0).target());var strong=p.route(new ConsistencyRoutingPolicy.Request(ConsistencyRoutingPolicy.Intent.STRONG_READ,0,Duration.ZERO),99);assertTrue(strong.readOnly());assertEquals("REPEATABLE_READ",strong.isolation());var stale=p.route(new ConsistencyRoutingPolicy.Request(ConsistencyRoutingPolicy.Intent.EVENTUAL_READ,10,Duration.ofSeconds(2)),9);assertEquals(ConsistencyRoutingPolicy.Target.PRIMARY,stale.target());assertEquals(ConsistencyRoutingPolicy.Target.REPLICA,p.route(new ConsistencyRoutingPolicy.Request(ConsistencyRoutingPolicy.Intent.EVENTUAL_READ,10,Duration.ofSeconds(2)),10).target());}}
